func cliCloseoutStateForStore(store posemodel.Store, ref string) (posemodel.CloseoutState, error) {
	scope, err := posemodel.ParseScopeRef(ref)
	if err != nil {
		return posemodel.CloseoutState{}, err
	}
	if scope.Kind != "roadmap" && scope.Kind != "milestone" {
		return store.GetCloseoutState(ref)
	}
	project := store.FederatedProjectID
	if project == "" {
		project, err = store.WriteProjectID()
		if err != nil {
			return posemodel.CloseoutState{}, fmt.Errorf("invalid project configuration")
		}
	}
	resolver := store.FederatedResolver
	if resolver == nil {
		value, _, resolverErr := posemodel.EnvironmentArtifactResolverIn(store.FS, store.Root, "")
		if resolverErr != nil {
			return posemodel.CloseoutState{}, fmt.Errorf("invalid project configuration")
		}
		resolver = &value
	}
	return store.GetCloseoutStateWithFederatedAcceptance(ref, project, *resolver)
}

func parseScopeCheckArgs(command string, args []string, stderr io.Writer) (string, bool, bool) {
	jsonFlag := " [--json]"
	if command == "close" {
		jsonFlag = ""
	}
	jsonOutput := false
	ref := ""
	for _, arg := range args {
		switch arg {
		case "--json":
			jsonOutput = true
		default:
			if strings.HasPrefix(arg, "-") || ref != "" {
				fmt.Fprintf(stderr, "Usage: pose %s <spec:slug|milestone:roadmap/id|roadmap:slug>%s\n", command, jsonFlag)
				return "", false, false
			}
			ref = arg
		}
	}
	if ref == "" {
		fmt.Fprintf(stderr, "Usage: pose %s <spec:slug|milestone:roadmap/id|roadmap:slug>%s\n", command, jsonFlag)
		return "", false, false
	}
	return ref, jsonOutput, true
}

func writeJSON(w io.Writer, value any) int {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	if err := enc.Encode(value); err != nil {
		return 1
	}
	return 0
}

func cmdReview(root string, args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprintln(stderr, "Usage: pose review <bundle|brief|attest|auto-attest|verify|record|attribution-supplement> ...")
		return 2
	}
	if code, handled := routeQualifiedReviewScope(root, args, stdout, stderr); handled {
		return code
	}
	switch args[0] {
	case "bundle":
		return cmdReviewBundle(root, args[1:], stdout, stderr)
	case "brief":
		return cmdReviewBrief(root, args[1:], stdout, stderr)
	case "run-sign":
		return cmdReviewRunSign(root, args[1:], stdout, stderr)
	case "run-proof":
		return cmdReviewRunProof(root, args[1:], stdout, stderr)
	case "conclude":
		return cmdReviewConclude(root, args[1:], stdout, stderr)
	case "request":
		return cmdReviewRequest(root, args[1:], stdout, stderr)
	// The aliases pose-delegation-surface deprecated are removed (spec
	// pose-delegation-parity-gate R6, D2): each names its replacement and runs
	// nothing.
	case "resume", "status", "dispatch":
		replacement := map[string]string{"dispatch": "pose delegate review|adjudicate|smoke <scope|bundle-id>", "resume": "pose delegate resume <run>", "status": "pose delegate ls"}[args[0]]
		return usageError(stderr, tr("pose review "+args[0]+" was removed; use "+replacement, "pose review "+args[0]+" foi removido; use "+replacement))
	case "attest":
		return cmdReviewAttest(root, args[1:], stdout, stderr)
	case "auto-attest":
		return cmdReviewAutoAttest(root, args[1:], stdout, stderr)
	case "verify":
		return cmdReviewVerify(root, args[1:], stdout, stderr)
	case "record":
